/**
 * RecordSearchService
 *
 * Security-focused dynamic SOQL search service for the "record finder" Lightning component.
 *
 * Security measures:
 *  - All object / field API names are resolved against the describe data (case-insensitive);
 *    only real, accessible-to-the-running-user names are ever injected into the query text.
 *  - All filter VALUES are bound as Apex bind variables (never concatenated), preventing SOQL
 *    injection.
 *  - WITH USER_MODE is used so the query enforces field-level security and sharing of the
 *    running user.
 *  - Objects and fields that the running user cannot read cause a SearchException, and
 *    non-filterable / non-sortable fields are rejected.
 */
public with sharing class RecordSearchService {

    private static final Integer MIN_ROWS = 1;
    private static final Integer MAX_ROWS = 200;

    /**
     * Exception thrown for every validation or access failure in this service.
     */
    public class SearchException extends Exception {
    }

    /**
     * Runs a single dynamic SOQL query built from validated, whitelisted identifiers and
     * bind-variable filter values.
     *
     * @param objectApiName  API name of the object to search (case-insensitive).
     * @param fields         API names of fields to select (case-insensitive).
     * @param filters        Map of field API name -> literal value; one equality condition each,
     *                       combined with AND. Null/empty means no WHERE clause. Values may be
     *                       String, Boolean, Date, Decimal, Integer, Id or null.
     * @param orderByField   Optional field API name to ORDER BY ascending (case-insensitive).
     * @param maxRows        LIMIT value; must be between 1 and 200 inclusive.
     * @return The queried records (List<SObject>).
     * @throws SearchException on any validation or access failure.
     */
    public static List<SObject> search(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        // ----- Validate LIMIT -------------------------------------------------------------
        if (maxRows == null || maxRows < MIN_ROWS || maxRows > MAX_ROWS) {
            throw new SearchException(
                'maxRows must be between ' + MIN_ROWS + ' and ' + MAX_ROWS + ' inclusive.'
            );
        }

        // ----- Validate SELECT fields -----------------------------------------------------
        if (fields == null || fields.isEmpty()) {
            throw new SearchException('At least one field must be requested.');
        }

        // ----- Resolve the object (case-insensitive, must be readable by the user) --------
        Schema.SObjectType sobjType = resolveObjectType(objectApiName);

        // ----- Validate object-level read access ------------------------------------------
        Schema.DescribeSObjectResult describe = sobjType.getDescribe();
        if (!describe.isAccessible()) {
            throw new SearchException(
                'You do not have access to the object: ' + objectApiName
            );
        }

        Map<String, Schema.SObjectField> fieldMap = describe.fields.getMap();

        // ----- Resolve / validate the SELECT fields ----------------------------------------
        List<String> selectColumns = new List<String>{ 'Id' };
        Set<String> seenSelect = new Set<String>{ 'id' };
        for (String fieldName : fields) {
            String resolved = resolveFieldName(fieldMap, fieldName, 'SELECT');
            if (!seenSelect.contains(resolved.toLowerCase())) {
                seenSelect.add(resolved.toLowerCase());
                selectColumns.add(resolved);
            }
        }

        // ----- Resolve / validate filter fields ---------------------------------------------
        // Deterministic ordering (sorted keys) so the generated WHERE clause is stable.
        List<String> filterFieldOrder = new List<String>();
        Map<String, Object> resolvedFilters = new Map<String, Object>();
        if (filters != null && !filters.isEmpty()) {
            List<String> keys = new List<String>(filters.keySet());
            keys.sort();
            for (String key : keys) {
                String resolved = resolveFieldName(fieldMap, key, 'filter');
                Schema.DescribeFieldResult fdr =
                    fieldMap.get(resolved.toLowerCase()).getDescribe();
                if (!fdr.isFilterable()) {
                    throw new SearchException(
                        'The field ' + resolved + ' cannot be used in a filter.'
                    );
                }
                filterFieldOrder.add(resolved);
                resolvedFilters.put(resolved, filters.get(key));
            }
        }

        // ----- Resolve / validate the ORDER BY field ------------------------------------------
        String resolvedOrderBy = null;
        if (orderByField != null && orderByField.trim() != '') {
            resolvedOrderBy = resolveFieldName(fieldMap, orderByField, 'ORDER BY');
            Schema.DescribeFieldResult fdr =
                fieldMap.get(resolvedOrderBy.toLowerCase()).getDescribe();
            if (!fdr.isSortable()) {
                throw new SearchException(
                    'The field ' + resolvedOrderBy + ' cannot be used for sorting.'
                );
            }
        }

        // ----- Build the query ------------------------------------------------------------------
        // SOQL clause order: SELECT ... FROM ... [WHERE ...] WITH USER_MODE [ORDER BY ...]
        // [LIMIT n]. WITH USER_MODE must come after WHERE (and after the object name when
        // there is no WHERE).
        String query = '';
        query += 'SELECT ';
        query += String.join(selectColumns, ', ');
        query += ' FROM ';
        query += describe.getName(); // safe: from describe, never raw user input

        // Bind filter values (injection-safe) using a wrapper list so the WHERE clause
        // can reference them positionally: filterBindings[0], filterBindings[1], ...
        List<Object> filterBindings = new List<Object>();
        if (!filterFieldOrder.isEmpty()) {
            query += ' WHERE ';
            Boolean first = true;
            for (String fieldName : filterFieldOrder) {
                if (!first) {
                    query += ' AND ';
                }
                first = false;
                query += fieldName;
                Object value = resolvedFilters.get(fieldName);
                if (value == null) {
                    query += ' = null';
                } else {
                    filterBindings.add(value);
                    query += ' = :filterBindings[' + (filterBindings.size() - 1) + ']';
                }
            }
        }

        query += ' WITH USER_MODE';

        if (resolvedOrderBy != null) {
            query += ' ORDER BY ';
            query += resolvedOrderBy;
            query += ' ASC';
        }

        query += ' LIMIT ';
        query += String.valueOf(maxRows); // already validated as an Integer 1..200

        try {
            return Database.query(query);
        } catch (Exception e) {
            // Any unexpected failure still surfaces as the service's exception type.
            throw new SearchException('Query failed: ' + e.getMessage(), e);
        }
    }

    /**
     * Resolves a user-supplied object API name (case-insensitively) to an SObjectType.
     * @throws SearchException if the object does not exist.
     */
    private static Schema.SObjectType resolveObjectType(String objectApiName) {
        if (objectApiName == null || objectApiName.trim() == '') {
            throw new SearchException('An object API name is required.');
        }
        Map<String, Schema.SObjectType> globalMap = Schema.getGlobalDescribe();
        Schema.SObjectType sobjType = globalMap.get(objectApiName.toLowerCase());
        if (sobjType == null) {
            throw new SearchException('The object does not exist: ' + objectApiName);
        }
        return sobjType;
    }

    /**
     * Resolves a user-supplied field API name (case-insensitively) against the object's
     * field describe map, verifying read access.
     * @return The exact (correct-case) field API name, safe to embed in SOQL.
     * @throws SearchException if the field does not exist or is not readable.
     */
    private static String resolveFieldName(
        Map<String, Schema.SObjectField> fieldMap,
        String fieldName,
        String usage
    ) {
        if (fieldName == null || fieldName.trim() == '') {
            throw new SearchException('A ' + usage + ' field name is required.');
        }
        Schema.SObjectField field = fieldMap.get(fieldName.toLowerCase());
        if (field == null) {
            throw new SearchException(
                'The field ' + fieldName + ' does not exist on this object.'
            );
        }
        Schema.DescribeFieldResult fdr = field.getDescribe();
        if (!fdr.isAccessible()) {
            throw new SearchException(
                'You do not have access to the field: ' + fdr.getName()
            );
        }
        return fdr.getName(); // exact API name from the describe - safe for SOQL
    }
}
```

The fix: `WITH USER_MODE` was being emitted immediately after the `FROM` clause, which made a following `WHERE` clause an invalid token. In SOQL, `WITH USER_MODE` must come **after** the `WHERE` clause (or straight after the object name when there is no `WHERE`). The query is now built in the correct order: `SELECT ... FROM ... [WHERE ...] WITH USER_MODE [ORDER BY ... ASC] LIMIT n`.

`Decimal.multiply` isn't accessible in Apex; replaced with the `*` operator.

