@IsTest
private class OpportunityWonHandlerTest {

    private static final String WON = 'Closed Won';
    private static final String HANDOVER = 'Handover to Customer Success';

    private static Opportunity makeOpp(Id accId) {
        return new Opportunity(
            Name = 'Test Opp',
            StageName = 'Prospecting',
            Amount = 100,
            CloseDate = Date.today().addDays(30),
            AccountId = accId
        );
    }

    @IsTest
    static void insertWonSetsNextStepCreatesTaskAndRatesAccount() {
        Account acc = new Account(Name = 'Acme', Rating = 'Cold');
        insert acc;

        Opportunity o = makeOpp(acc.Id);
        o.StageName = WON;
        Test.startTest();
        insert o;
        Test.stopTest();

        Opportunity result = [SELECT NextStep, StageName, OwnerId, CloseDate FROM Opportunity WHERE Id = :o.Id];
        System.assertEquals(HANDOVER, result.NextStep, 'NextStep should be set on insert as won');

        List<Task> tasks = [SELECT Subject, WhatId, OwnerId, ActivityDate, Priority FROM Task WHERE WhatId = :o.Id];
        System.assertEquals(1, tasks.size(), 'Exactly one task should be created');
        Task t = tasks[0];
        System.assertEquals('Customer kick-off', t.Subject);
        System.assertEquals(o.Id, t.WhatId);
        System.assertEquals(result.OwnerId, t.OwnerId, 'Task owner should be the opportunity owner');
        System.assertEquals(result.CloseDate.addDays(7), t.ActivityDate, 'ActivityDate should be CloseDate + 7 days');
        System.assertEquals('High', t.Priority);

        Account accAfter = [SELECT Rating FROM Account WHERE Id = :acc.Id];
        System.assertEquals('Hot', accAfter.Rating, 'Account should be rated Hot');
    }

    @IsTest
    static void insertWonWithoutAccountStillCreatesTask() {
        Opportunity o = makeOpp(null);
        o.StageName = WON;
        Test.startTest();
        insert o;
        Test.stopTest();

        Opportunity result = [SELECT NextStep FROM Opportunity WHERE Id = :o.Id];
        System.assertEquals(HANDOVER, result.NextStep);

        System.assertEquals(1, [SELECT COUNT() FROM Task WHERE WhatId = :o.Id], 'Task should exist without account');
    }

    @IsTest
    static void insertNotWonDoesNothing() {
        Account acc = new Account(Name = 'Acme', Rating = 'Cold');
        insert acc;

        Opportunity o = makeOpp(acc.Id);
        Test.startTest();
        insert o;
        Test.stopTest();

        Opportunity result = [SELECT NextStep FROM Opportunity WHERE Id = :o.Id];
        System.assertEquals(null, result.NextStep, 'NextStep should not be set for non-won insert');
        System.assertEquals(0, [SELECT COUNT() FROM Task WHERE WhatId = :o.Id], 'No task should be created');
        System.assertEquals('Cold', [SELECT Rating FROM Account WHERE Id = :acc.Id].Rating, 'Account rating unchanged');
    }

    @IsTest
    static void updateToWonDoesHandover() {
        Account acc = new Account(Name = 'Acme', Rating = 'Warm');
        insert acc;

        Opportunity o = makeOpp(acc.Id);
        insert o; // inserted as Prospecting, no handover yet

        Test.startTest();
        o.StageName = WON;
        update o;
        Test.stopTest();

        Opportunity result = [SELECT NextStep, StageName FROM Opportunity WHERE Id = :o.Id];
        System.assertEquals(WON, result.StageName);
        System.assertEquals(HANDOVER, result.NextStep, 'NextStep should be set on update to won');
        System.assertEquals(1, [SELECT COUNT() FROM Task WHERE WhatId = :o.Id]);
        System.assertEquals('Hot', [SELECT Rating FROM Account WHERE Id = :acc.Id].Rating);
    }

    @IsTest
    static void updateAlreadyWonDoesNothing() {
        Account acc = new Account(Name = 'Acme', Rating = 'Cold');
        insert acc;

