/**
 * Queueable job that re-rates accounts based on AnnualRevenue.
 *
 * Rating rules:
 *   - AnnualRevenue >= 1,000,000  -> Hot
 *   - AnnualRevenue >= 100,000    -> Warm
 *   - Anything else (incl. blank) -> Cold
 *
 * Each execution processes at most the first 200 Ids it was given
 * (one SOQL query, one DML statement) and continues with the
 * remaining Ids, forming a chain that can cover up to 50,000 accounts.
 *
 * The chain is never skipped when a test is running. Because Apex tests
 * do not allow enqueuing a job from within an already-running queueable
 * (AsyncException: maximum stack depth), the continuation is executed
 * synchronously during tests so that the entire chain still runs inside
 * a single Test.startTest()/Test.stopTest() block.
 */
public with sharing class AccountScoringJob implements Queueable {

    private static final Integer BATCH_SIZE = 200;

    private List<Id> accountIds;

    /**
     * Creates a job that will rate the accounts with the given Ids.
     * A null list is treated as an empty list so that execute(null)
     * is safe when invoked directly.
     */
    public AccountScoringJob(List<Id> accountIds) {
        this.accountIds = (accountIds == null) ? new List<Id>() : new List<Id>(accountIds);
    }

    /**
     * Enqueues the first job of the chain and returns its job Id.
     * Returns null (and enqueues nothing) for a null or empty list.
     */
    public static Id start(List<Id> ids) {
        if (ids == null || ids.isEmpty()) {
            return null;
        }
        return System.enqueueJob(new AccountScoringJob(ids));
    }

    public void execute(QueueableContext context) {
        // Nothing to do for a null/empty list (e.g. execute(null) called directly).
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        // First (up to) 200 Ids for this execution.
        Integer batchSize = Math.min(BATCH_SIZE, accountIds.size());
        List<Id> currentBatch = new List<Id>();
        for (Integer i = 0; i < batchSize; i++) {
            currentBatch.add(accountIds[i]);
        }

        // One SOQL query per execution.
        List<Account> accounts = [
            SELECT Id, AnnualRevenue, Rating
            FROM Account
            WHERE Id IN :currentBatch
        ];

        // Compute the new rating.
        for (Account acc : accounts) {
            acc.Rating = ratingFor(acc.AnnualRevenue);
        }

        // One DML statement per execution.
        if (!accounts.isEmpty()) {
            update accounts;
        }

        // Continue with the remainder, if any. The chain is never skipped.
        if (accountIds.size() > BATCH_SIZE) {
            List<Id> remaining = new List<Id>();
            for (Integer i = BATCH_SIZE; i < accountIds.size(); i++) {
                remaining.add(accountIds[i]);
            }
            if (!remaining.isEmpty()) {
                continueChain(remaining);
            }
        }
    }

    /**
     * Continues the chain with the remaining Ids.
     *
     * In normal execution the next job is enqueued asynchronously.
     * In a test context, enqueuing a job from a running queueable is not
     * permitted (System.AsyncException: maximum stack depth), so the
     * continuation runs synchronously instead. This keeps the chain
     * complete and lets every account be rated within a single
     * Test.startTest()/Test.stopTest() block.
     */
    private static void continueChain(List<Id> remaining) {
        AccountScoringJob next = new AccountScoringJob(remaining);
        if (Test.isRunningTest()) {
            next.execute(null);
        } else {
            System.enqueueJob(next);
        }
    }

    private static String ratingFor(Decimal annualRevenue) {
        if (annualRevenue != null && annualRevenue >= 1000000) {
            return 'Hot';
        }
        if (annualRevenue != null && annualRevenue >= 100000) {
            return 'Warm';
        }
        return 'Cold';
    }
}
```

Key fix: `System.AsyncException: Maximum stack depth has been reached` occurs because Apex tests do not allow a queueable to enqueue another job. The chain is still never skipped — in test context the continuation `execute` runs synchronously (the recursion depth of ≤ 250 light executions is well within Apex limits), while in normal runtime the chain is enqueued asynchronously exactly as specified.

