/**
 * Domain class for Opportunity.
 * Validation rules:
 *   1. Amount must not be negative (insert and update).
 *   2. Amount cannot change on an opportunity that was already Closed Won (update only).
 *      Closing as won and changing amount in the same update is allowed.
 */
public inherited sharing class Opportunities extends fflib_SObjectDomain {

    private static final String STAGE_CLOSED_WON = 'Closed Won';

    public Opportunities(List<Opportunity> records) {
        super(records);
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> records) {
            List<Opportunity> opportunities = new List<Opportunity>();
            for (SObject record : records) {
                opportunities.add((Opportunity) record);
            }
            return new Opportunities(opportunities);
        }
    }

    // Rule 1: applies on insert and update (fflib invokes onValidate for both).
    public override void onValidate() {
        for (Opportunity opp : (List<Opportunity>) Records) {
            if (opp.Amount != null && opp.Amount < 0) {
                addError('Amount cannot be negative.', opp);
            }
        }
    }

    // Rule 2: applies on update only. fflib passes the pre-update records.
    public override void onBeforeUpdate(Map<Id, SObject> existingRecords) {
        for (Opportunity opp : (List<Opportunity>) Records) {
            Opportunity prior = (Opportunity) existingRecords.get(opp.Id);
            if (prior == null) {
                continue;
            }
            Boolean wasAlreadyWon = prior.StageName == STAGE_CLOSED_WON;
            if (wasAlreadyWon && opp.Amount != prior.Amount) {
                addError('Amount cannot change on a won opportunity.', opp);
            }
        }
    }

    private void addError(String message, Opportunity opp) {
        // fflib records the message in fflib_SObjectDomain.Errors and
        // attaches it to the offending record's Amount field only.
        error(message, opp, Opportunity.Fields.Amount);
    }
}
