public inherited sharing class OpportunityWinService {

    public static Integer markWon(Set<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        List<Opportunity> opportunities =
            OpportunitiesSelector.newInstance().selectById(opportunityIds);

        if (opportunities == null || opportunities.isEmpty()) {
            return 0;
        }

        fflib_SObjectUnitOfWork uow = Application.UnitOfWork.newInstance();

        Integer closed = 0;
        for (Opportunity opp : opportunities) {
            if (opp.StageName == 'Closed Won') {
                continue;
            }

            opp.StageName = 'Closed Won';
            opp.CloseDate = Date.today();
            uow.registerDirty(opp);

            Deal_Won__e event = new Deal_Won__e(
                Opportunity_Id__c = opp.Id,
                Amount__c = opp.Amount
            );
            // Publish only after the opportunity updates have committed
            // successfully; if the commit fails, nothing is published.
            uow.registerPublishAfterTransaction(event);

            closed++;
        }

        uow.commitWork();

        return closed;
    }
}
