        if (relevant && opp.AccountId != null) {
            accountIds.add(opp.AccountId);
        }
    }

    if (!accountIds.isEmpty()) {
        AccountRatingService.recalculate(accountIds);
    }

    private static Boolean isOpen(Opportunity o) {
        return o != null && isStageOpen(o.StageName);
    }

    private static Boolean isStageOpen(String stage) {
        return stage != null &&
