trigger CaseTrigger on Case (after update) {
    if (!Trigger.isUpdate || !Trigger.isAfter) {
        return;
    }

    // Collect newly closed cases with a contact (not-closed -> closed).
    List<Id> caseIds = new List<Id>();
    for (Case newCase : Trigger.new) {
        Case oldCase = Trigger.oldMap.get(newCase.Id);
        Boolean wasClosed = (oldCase != null && oldCase.IsClosed);
        if (newCase.IsClosed && !wasClosed && newCase.ContactId != null) {
            caseIds.add(newCase.Id);
        }
    }
    if (caseIds.isEmpty()) {
        return;
    }

    // System.enqueueJob is limited to 50 calls per transaction; a bulk
    // close (e.g. nightly API job, up to 200 cases) exceeds that. Enqueue
    // at most 50 jobs; overflow case Ids are carried by the last job,
    // which chains itself so every case still runs in its own job.
    final Integer MAX_ENQUEUE = 50;
    for (Integer i = 0; i < caseIds.size(); i++) {
        if (i < MAX_ENQUEUE - 1) {
            System.enqueueJob(new CaseSurveyJob(caseIds[i]));
        } else {
            List<Id> tail = new List<Id>();
            for (Integer j = i + 1; j < caseIds.size(); j++) {
                tail.add(caseIds[j]);
            }
            System.enqueueJob(new CaseSurveyJob(caseIds[i], tail));
            break;
        }
    }
}
