```js
import { LightningElement, api } from 'lwc';

const HANDLED_KEYS = new Set([
    'ArrowDown',
    'ArrowUp',
    'Home',
    'End',
    'Enter',
    ' '
]);

export default class StatusListbox extends LightningElement {
    @api label;

    _options = [];
    _value = '';
    _activeIndex = 0;
    _uid = `slb-${Math.random().toString(36).slice(2, 10)}`;

    @api
    get options() {
        return this._options;
    }
    set options(value) {
        this._options = (value || []).map((opt, index) => ({
            ...opt,
            key: `${index}-${opt.value}`
        }));
        this._syncActiveWithSelection();
    }

    @api
    get value() {
        return this._value;
    }
    set value(newValue) {
        this._value = newValue == null ? '' : newValue;
        this._syncActiveWithSelection();
    }

    get computedOptions() {
        return this._options.map((opt, index) => ({
            ...opt,
            id: this._optionId(index),
            className: index === this._activeIndex ? 'active' : '',
            ariaSelected: opt.value === this._value ? 'true' : 'false'
        }));
    }

    get activeDescendantId() {
        if (this._options.length === 0) {
            return null;
        }
        return this._optionId(this._activeIndex);
    }

    _optionId(index) {
        return `${this._uid}-option-${index}`;
    }

    _syncActiveWithSelection() {
        if (this._options.length === 0) {
            this._activeIndex = 0;
            return;
        }
        const index = this._options.findIndex(
            (opt) => opt.value === this._value
        );
        this._activeIndex = index >= 0 ? index : 0;
    }

    handleKeydown(event) {
        const key = event.key;
        if (!HANDLED_KEYS.has(key)) {
            return;
        }
        event.preventDefault();

        if (this._options.length === 0) {
            return;
        }

        switch (key) {
            case 'ArrowDown':
                this._activeIndex = Math.min(
                    this._activeIndex + 1,
                    this._options.length - 1
                );
                break;
            case 'ArrowUp':
                this._activeIndex = Math.max(this._activeIndex - 1, 0);
                break;
            case 'Home':
                this._activeIndex = 0;
                break;
            case 'End':
                this._activeIndex = this._options.length - 1;
                break;
            case 'Enter':
            case ' ':
                this._selectIndex(this._activeIndex);
                break;
            default:
                break;
        }
    }

    handleClick(event) {
        const target = event.target.closest('[data-value]');
        if (!target) {
            return;
        }
        const dataValue = target.getAttribute('data-value');
        const index = this._options.findIndex(
            (opt) => opt.value === dataValue
        );
        if (index < 0) {
            return;
        }
        this._activeIndex = index;
        this._selectIndex(index);
    }

    _selectIndex(index) {
        const option = this._options[index];
        if (!option || option.value === this._value) {
            return;
        }
        this._value = option.value;
        this.dispatchEvent(
            new CustomEvent('change', {
                detail: { value: option.value }
            })
        );
    }
}
