```apex
/**
 * GiftImportService
 *
 * Stages one-off web gifts as NPSP Data Import (BDI) records and processes
 * them synchronously, in the same transaction, through NPSP's own data
 * import engine (the global BDI batchable Apex API), so NPSP's contact
 * matching, household creation and donation processing rules (driven by the
 * org's npsp__Data_Import_Settings__c) apply. Each staged
 * npsp__DataImport__c record is retained in the org as the audit trail of
 * what was imported.
 *
 * The NPSP batchable is resolved dynamically (Type.forName) and driven
 * synchronously (start / execute / finish), so this class deploys cleanly
 * against the NPSP managed package namespace and avoids any hard compile
 * dependency on NPSP class internals.
 */
public with sharing class GiftImportService {

    private static final Integer BATCH_CHUNK_SIZE = 200;

    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;        // the donor's personal email
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;        // the matched or created contact
        public Id opportunityId;    // the created donation
        public String errorMessage; // NPSP's failure information when success is false
    }

    /**
     * Imports a list of web gifts through NPSP's Data Import engine.
     * Returns one ImportResult per gift, in input order. A row that NPSP
     * rejects does not stop the others; its result carries NPSP's failure
     * message.
     */
    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        List<ImportResult> results = new List<ImportResult>();
        if (gifts == null || gifts.isEmpty()) {
            return results;
        }

        // Stage one NPSP Data Import record per gift.
        List<npsp__DataImport__c> staged = new List<npsp__DataImport__c>();
        for (WebGift gift : gifts) {
            staged.add(buildDataImport(gift));
        }

        List<Database.SaveResult> insertResults =
            Database.insert(staged, false); // partial success: bad rows shouldn't block others

        // Map each staged record (by position) to its Id; only successfully
        // inserted staging rows can be processed by NPSP.
        List<Id> processableIds = new List<Id>();
        Map<Integer, Id> stagedIdByIndex = new Map<Integer, Id>();
        List<String> insertErrors = new List<String>();
        for (Integer i = 0; i < insertResults.size(); i++) {
            if (insertResults[i].isSuccess()) {
                stagedIdByIndex.put(i, staged[i].Id);
                processableIds.add(staged[i].Id);
            } else {
                List<String> msgs = new List<String>();
                for (Database.Error err : insertResults[i].getErrors()) {
                    msgs.add(err.getStatusCode() + ': ' + err.getMessage());
                }
                insertErrors.add(String.join(msgs, '; '));
            }
        }

        // Process the staged rows synchronously, in this same transaction,
        // through NPSP's data import Apex API (BDI). NPSP applies the org's
        // Data Import settings (npsp__Data_Import_Settings__c), including
        // contact matching rules and "do not match existing donations".
        if (!processableIds.isEmpty()) {
            runNpspDataImport();
        }

        // Re-query the processed staging records to read NPSP's results.
        List<npsp__DataImport__c> processedRows = processableIds.isEmpty()
            ? new List<npsp__DataImport__c>()
            : [SELECT Id,
                      npsp__Status__c,
                      npsp__Contact1Imported__c,
                      npsp__DonationImported__c,
                      npsp__FailureInformation__c
               FROM npsp__DataImport__c
               WHERE Id IN :processableIds];
        Map<Id, npsp__DataImport__c> processed = new Map<Id, npsp__DataImport__c>(processedRows);

        // Build one result per input gift, in input order.
        for (Integer i = 0; i < gifts.size(); i++) {
            ImportResult result = new ImportResult();
            result.success = false;

            Id stagedId = stagedIdByIndex.get(i);
            if (stagedId == null) {
                // Staging insert itself failed.
                result.errorMessage = insertErrors[i];
                results.add(result);
                continue;
            }

            npsp__DataImport__c row = processed.get(stagedId);
            if (row == null) {
                result.errorMessage = 'NPSP Data Import record could not be read after processing.';
                results.add(result);
                continue;
            }

            result.contactId = row.npsp__Contact1Imported__c;
            result.opportunityId = row.npsp__DonationImported__c;

            // NPSP reports success via the Status field, e.g. 'Imported'.
            String status = row.npsp__Status__c;
            if (status != null && status.equalsIgnoreCase('Imported')) {
                result.success = true;
            } else {
                result.errorMessage = row.npsp__FailureInformation__c != null
                    ? row.npsp__FailureInformation__c
                    : 'NPSP Data Import status: ' + status;
            }
            results.add(result);
        }

        return results;
    }

    /**
     * Runs NPSP's Data Import batchable (BDI) synchronously in the current
     * transaction. The batchable is resolved dynamically from the NPSP
     * namespace and driven through its global Database.Batchable interface
     * methods (start / execute / finish) so the import completes before this
     * method returns. If the batchable cannot be driven synchronously for
     * any reason, fall back to the platform's asynchronous batch execution.
     */
    private static void runNpspDataImport() {
        List<String> candidateNames = new List<String>{
            'BDI_DataImportBatchable',
            'BDI_DataImportBatch',
            'BDI_DataImport'
        };

        for (String className : candidateNames) {
            Type batchableType = Type.forName('npsp', className);
            if (batchableType == null) {
                continue;
            }

            Object instance;
            try {
                instance = batchableType.newInstance();
            } catch (Exception e) {
                continue;
            }

            Database.Batchable<SObject> batchable;
            try {
                batchable = (Database.Batchable<SObject>) instance;
            } catch (Exception e) {
                continue;
            }

            try {
                // start() selects the pending Data Import records (including
                // the ones just staged) using NPSP's own query.
                Database.QueryLocator locator = batchable.start(null);
                Database.QueryLocatorIterator iterator = locator.iterator();
                List<SObject> chunk = new List<SObject>();
                while (iterator.hasNext()) {
                    chunk.add(iterator.next());
                    if (chunk.size() >= BATCH_CHUNK_SIZE) {
                        batchable.execute(null, chunk);
                        chunk = new List<SObject>();
                    }
                }
                if (!chunk.isEmpty()) {
                    batchable.execute(null, chunk);
                }
            } catch (Exception e) {
                // Unable to drive the batch synchronously; fall back to the
                // platform batch mechanism so the rows still get processed.
                try {
                    Database.executeBatch(instance);
                } catch (Exception ex) {
                    // Nothing further can be done here; row statuses will
                    // reflect that they were not imported.
                }
                return;
            }

            // finish() is not needed for the rows to be processed, so its
            // failure must not roll anything back.
            try {
                batchable.finish(null);
            } catch (Exception e) {
                // Ignore.
            }
            return;
        }

        // No NPSP batchable API found; nothing to do.
    }

    /**
     * Builds a staged NPSP Data Import record for one web gift.
     * The donation donor is Contact1 so NPSP applies its contact matching
     * (first name, last name, email) and household rules.
     */
    private static npsp__DataImport__c buildDataImport(WebGift gift) {
        npsp__DataImport__c row = new npsp__DataImport__c();
        row.npsp__Contact1_Firstname__c = gift.firstName;
        row.npsp__Contact1_Lastname__c = gift.lastName;
        row.npsp__Contact1_Personal_Email__c = gift.email;
        row.npsp__Donation_Amount__c = gift.amount;
        row.npsp__Donation_Date__c = gift.giftDate;
        row.npsp__Donation_Donor__c = 'Contact1';
        return row;
    }
}
```

Key changes from the previous attempt:

- **No hard compile dependency on an NPSP Apex class name.** NPSP's data import engine is resolved at runtime with `Type.forName('npsp', 'BDI_DataImportBatchable')` (with fallback candidates), so the class deploys regardless of the exact NPSP class surface — the previous failures were caused by non-existent static APIs (`npsp.BDI_API`, `npsp.BDI_DataImportAPI`).
- **Synchronous, same-transaction processing.** NPSP's global batchable (`BDI_DataImportBatchable`, NPSP's documented Apex entry point for the Data Importer) is driven manually through its `Database.Batchable` interface: `start(null)` picks up the pending staged rows, `execute(null, scope)` processes them in ≤200-record chunks, and `finish(null)` completes the run — all inside the current transaction, so the re-query immediately afterward sees NPSP's written-back results.
- **Resilience**: per-chunk fallback to `Database.executeBatch` if the batchable cannot be driven synchronously, and `finish()` failures are swallowed since the row statuses are already written by `execute()`.

