```apex
public with sharing class GiftService {

    private static final String ROLE_DONOR = 'Donor';
    private static final String ROLE_HOUSEHOLD_MEMBER = 'Household Member';

    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {
        // ---- Validation ----
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException('amount must be a positive number');
        }

        List<Contact> donorList = [
            SELECT Id, FirstName, LastName, AccountId
            FROM Contact
            WHERE Id = :contactId
        ];
        if (donorList.isEmpty()) {
            throw new IllegalArgumentException('contact does not exist: ' + contactId);
        }
        Contact donor = donorList[0];
        if (donor.AccountId == null) {
            throw new IllegalArgumentException(
                'contact ' + contactId + ' has no household account'
            );
        }

        // ---- Opportunity ----
        String oppName = donor.FirstName + ' ' + donor.LastName
            + ' Donation ' + formatIso(giftDate);

        Opportunity opp = new Opportunity(
            Name = oppName,
            AccountId = donor.AccountId,
            Amount = amount,
            CloseDate = giftDate,
            StageName = 'Closed Won',
            npsp__Primary_Contact__c = donor.Id
        );
        insert opp;

        // NPSP automation may create contact roles and/or a payment when the
        // opportunity is inserted as Closed Won, so reconcile rather than
        // blindly inserting.

        // ---- Contact roles: exactly one per household member ----
        // Household members other than the donor -> "Household Member".
        Map<Id, String> desiredRolesByContact = new Map<Id, String>();
        for (Contact member : [
            SELECT Id
            FROM Contact
            WHERE AccountId = :donor.AccountId
        ]) {
            desiredRolesByContact.put(
                member.Id,
                member.Id == donor.Id ? ROLE_DONOR : ROLE_HOUSEHOLD_MEMBER
            );
        }

        // Roles that already exist (e.g. auto-created by NPSP).
        Map<Id, OpportunityContactRole> existingRoleByContact = new Map<Id, OpportunityContactRole>();
        for (OpportunityContactRole ocr : [
            SELECT Id, ContactId, Role, IsPrimary
            FROM OpportunityContactRole
            WHERE OpportunityId = :opp.Id
        ]) {
            if (existingRoleByContact.containsKey(ocr.ContactId)) {
                // More than one role for the same contact: keep the first,
                // delete the extra so no contact has two roles.
                delete ocr;
            } else {
                existingRoleByContact.put(ocr.ContactId, ocr);
            }
        }

        List<OpportunityContactRole> toInsert = new List<OpportunityContactRole>();
        List<OpportunityContactRole> toUpdate = new List<OpportunityContactRole>();
        for (Id contactKey : desiredRolesByContact.keySet()) {
            String desiredRole = desiredRolesByContact.get(contactKey);
            Boolean desiredPrimary = (contactKey == donor.Id);

            OpportunityContactRole existing = existingRoleByContact.get(contactKey);
            if (existing == null) {
                toInsert.add(new OpportunityContactRole(
                    OpportunityId = opp.Id,
                    ContactId = contactKey,
                    Role = desiredRole,
                    IsPrimary = desiredPrimary
                ));
            } else if (existing.Role != desiredRole || existing.IsPrimary != desiredPrimary) {
                existing.Role = desiredRole;
                existing.IsPrimary = desiredPrimary;
                toUpdate.add(existing);
            }
        }
        if (!toInsert.isEmpty()) {
            insert toInsert;
        }
        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }

        // ---- Exactly one payment: paid, full amount, dated giftDate ----
        List<npe01__OppPayment__c> payments = [
            SELECT Id, npe01__Payment_Amount__c, npe01__Payment_Date__c,
                   npe01__Scheduled_Date__c, npe01__Paid__c
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :opp.Id
            ORDER BY CreatedDate ASC
        ];

        if (payments.isEmpty()) {
            insert new npe01__OppPayment__c(
                npe01__Opportunity__c = opp.Id,
                npe01__Payment_Amount__c = amount,
                npe01__Payment_Date__c = giftDate,
                npe01__Scheduled_Date__c = giftDate,
                npe01__Paid__c = true
            );
        } else {
            // Update the first payment to the required state and remove any
            // extras so there is no duplicate payment.
            npe01__OppPayment__c keep = payments[0];
            Boolean changed = keep.npe01__Payment_Amount__c != amount
                || keep.npe01__Payment_Date__c != giftDate
                || keep.npe01__Scheduled_Date__c != giftDate
                || keep.npe01__Paid__c != true;
            if (changed) {
                keep.npe01__Payment_Amount__c = amount;
                keep.npe01__Payment_Date__c = giftDate;
                keep.npe01__Scheduled_Date__c = giftDate;
                keep.npe01__Paid__c = true;
                update keep;
            }
            List<npe01__OppPayment__c> extras = payments.clone();
            extras.remove(0);
            if (!extras.isEmpty()) {
                delete extras;
            }
        }

        return opp.Id;
    }

    /**
     * Formats a Date as yyyy-MM-dd in a locale-independent way.
     */
    private static String formatIso(Date d) {
        if (d == null) {
            return null;
        }
        return String.valueOf(d.year()) + '-'
            + padTwo(d.month()) + '-'
            + padTwo(d.day());
    }

    private static String padTwo(Integer n) {
        return n < 10 ? '0' + String.valueOf(n) : String.valueOf(n);
    }
}
```

Summary of the fixes:

1. **Duplicate donor contact role**: NPSP automatically creates a contact role when `npsp__Primary_Contact__c` is set, so our unconditional insert produced a second `Donor` role. The class now queries existing roles after inserting the opportunity, updates the existing role to the desired `Role`/`IsPrimary` values, deletes any extra roles for the same contact, and only inserts roles for contacts that have none.
2. **`QueryException: List has no rows`**: the contact lookup now queries into a `List<Contact>` and throws `IllegalArgumentException` when empty, instead of relying on direct SObject assignment (which throws `QueryException` before we can check).
3. **Duplicate payment**: instead of skipping insertion only when a payment already existed, the method now reconciles — it updates the earliest payment to paid/full amount/`giftDate` and deletes any extra payments, guaranteeing exactly one payment regardless of NPSP automation.

